issue_context.body:
The following code will successfully serialize an ed25519 key (or ed448 key if you swap the NID) as a PKCS8 structure in both PEM and DER encoding on OpenSSL 1.1.1, but errors on 3.0.0-alpha2.

```c
#include <stdio.h>
#include <openssl/bio.h>
#include <openssl/evp.h>
#include <openssl/pem.h>
#include <openssl/obj_mac.h>
int main(void) {
    int res = 0;

    EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(NID_ED25519, NULL);
    res = EVP_PKEY_keygen_init(ctx);
    if (res != 1) {
        printf("could not init keygen\n");
        return 1;
    }
    EVP_PKEY *pkey;
    res = EVP_PKEY_keygen(ctx, &pkey);
    if (res != 1) {
        printf("could not generate key\n");
        return 2;
    }
    BIO *bio = BIO_new(BIO_s_mem());
    res = PEM_write_bio_PKCS8PrivateKey(bio, pkey, NULL, "", 0, NULL, NULL);
    if (res != 1) {
        printf("failed to serialize to PEM\n");
    }
    res = i2d_PKCS8PrivateKey_bio(bio, pkey, NULL, "", 0, NULL, NULL);
    if (res != 1) {
        printf("failed to serialize to DER\n");
    }

    return 0;
}
```
